// AQ Developer CV download helper. The CV is embedded so the download works even when index.html is opened from file://.
const AQ_CV_FILENAME = 'AQ-Developer-CV.png';
const AQ_CV_BASE64 = "";

function aqDownloadCV(event) {
  if (event) event.preventDefault();
  try {
    const binary = atob(AQ_CV_BASE64);
    const bytes = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
    const blob = new Blob([bytes], { type: 'image/png' });
    const objectURL = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = objectURL;
    link.download = AQ_CV_FILENAME;
    link.rel = 'noopener';
    document.body.appendChild(link);
    link.click();
    link.remove();
    setTimeout(() => URL.revokeObjectURL(objectURL), 2500);
  } catch (error) {
    // Last-resort fallback: open the CV so it can be saved manually.
    const fallback = document.querySelector('[data-cv-fallback]');
    if (fallback) window.location.href = fallback.getAttribute('href');
  }
}

document.addEventListener('DOMContentLoaded', () => {
  document.querySelectorAll('.cv-download').forEach((button) => {
    button.addEventListener('click', aqDownloadCV);
  });
});
